# Theme re-apply fan-out. The Command Center's own chrome (header, rail, detail
# column) bakes C.* values into stylesheets and vector icons at build time, so a
# dark/light flip has to re-run that work. Each widget registers a zero-arg
# closure here; C.apply_mode calls them after the tokens move, which is the same
# re-polish the accent picker already drives through C._listeners for the older
# pages. Keeping it beside the constants means the startup apply_mode() call
# finds the list already bound.
_THEME_REAPPLY: list = []


def register_theme_reapply(fn) -> None:
    if fn not in _THEME_REAPPLY:
        _THEME_REAPPLY.append(fn)


class C:
    """The Saturn Cyberpunk token set - the only palette the Qt shell reads colours from.

    Taken from the delivered design (saturn_package: design/tokens.md +
    qml/Theme.qml): a near-black base, purple-tinted surfaces, magenta accent
    with an acid-yellow secondary, and the four orb states. The old Aurum gold
    identity is fully retired here - every brand value below is cyberpunk, and
    nothing in here may hold a gold or cyan value. The gold-named constants are
    kept (GOLD, GOLD_DEEP, ...) purely so the 200+ existing C.* call sites
    inherit the new palette without a rename; the name is history, the value is
    magenta.
    """
    GOLD      = "#FF2BD6"   # brand accent - magenta; name kept for call sites
    GOLD_DEEP = "#C2009E"   # darker magenta (light-mode accent)
    GOLD_LT   = "#F3EDFF"   # near-white ink / lightest tint
    GOLD_MID  = "#9B5CFF"   # purple gradient end of every primary button
    ON_GOLD   = "#0D0716"   # ink drawn on a magenta fill
    UNSET     = "#6E6A7C"   # a service with no credentials at all (muted)
    # Orb states. The page keeps its own copy for the 3D reactor.
    S_IDLE    = ("#FF2BD6", "#C2009E", "#FF9BEF")
    S_LISTEN  = ("#B6FF3B", "#3F7D00", "#E4FFB0")
    S_THINK   = ("#F5E94B", "#FF7A2B", "#FFF6A8")
    S_SPEAK   = ("#FF2BD6", "#9B5CFF", "#D9A6FF")
    S_SPEAK_SPECTRUM = ("#FF2BD6", "#9B5CFF", "#F5E94B", "#B6FF3B")

    BG        = "#05030A"
    EMBER     = "#1A0A26"
    PANEL     = "#0D0716"
    PANEL2    = "#1A0A26"
    HI        = "#1A0A26"   # design: --hi (raised surface for inputs / hover fills)
    BORDER    = "rgba(58, 33, 82, 0.85)"      # line #3A2152
    BORDER_B  = "rgba(255, 43, 214, 0.45)"    # accent-tinted strong border
    BORDER_A  = "rgba(243, 237, 255, 0.16)"   # near-white hairline
    PRI       = GOLD
    PRI_DIM   = "#C2009E"
    PRI_GHO   = "rgba(255, 43, 214, 0.12)"
    PRI_GRAD  = "#9B5CFF"   # second stop of every accent-filled control
    GLASS     = "rgba(255, 43, 214, 0.06)"    # card and chip fill
    GLASS_BRIGHT = "rgba(255, 43, 214, 0.09)" # assistant bubble fill
    BUBBLE_EDGE  = "rgba(255, 43, 214, 0.24)" # assistant bubble border
    ACC       = GOLD
    ACC2      = "#F5E94B"   # acid yellow - the design's secondary accent
    FEATURE   = "#2BE4FF"   # feature cyan - the FEATURE tier badge / header count
    FEATURE_D = "#006E84"   # light-mode feature cyan
    GREEN     = "#B6FF3B"   # listening green
    GREEN_D   = "#3F7D00"
    RED       = "#FF2B4A"   # error red
    MUTED_C   = GOLD
    TEXT      = "#F3EDFF"
    TEXT_DIM  = "#9A8FB5"
    TEXT_MED  = "#C9C2DC"
    WHITE     = GOLD_LT
    DARK      = ON_GOLD
    BAR_BG    = "#0D0716"
    # Historical names kept so existing call sites keep working, now magenta.
    ICE       = GOLD
    ICE_DIM   = GOLD_DEEP
    ICE_GHO   = "rgba(255, 43, 214, 0.15)"
    # Type tokens. theme_fonts.install() upgrades F_DISPLAY to the bundled
    # Unbounded face as soon as assets/fonts has the file; body and mono are
    # Segoe UI and Consolas, which ship with Windows and match the design, so
    # they need no download.
    F_BODY    = "Segoe UI"      # design: Segoe UI
    F_DISPLAY = "Segoe UI"      # design: Unbounded (bundled at startup)
    F_MONO    = "Consolas"      # design: Consolas
    # Glyph face for line icons (mic/attach/send/tray). Segoe MDL2 Assets ships
    # on every Windows 10/11 install, and its private-use-area glyphs render as
    # monochrome vectors that inherit the stylesheet colour -- unlike color emoji
    # (🎙📎➤), which ignore the palette and arrive as inconsistent bitmaps.
    F_ICON    = "Segoe MDL2 Assets"
    _listeners: list = []

    @classmethod
    def register_listener(cls, callback):
        if callback not in cls._listeners:
            cls._listeners.append(callback)

    @classmethod
    def unregister_listener(cls, callback):
        if callback in cls._listeners:
            cls._listeners.remove(callback)

    @classmethod
    def load_theme(cls, theme_hex: str):
        if not theme_hex.startswith("#") or len(theme_hex) != 7:
            # A word or a non-hex. The legacy brand aliases (gold/aurum/amber)
            # now resolve to the cyberpunk accent; anything unrecognised means
            # "no accent chosen" and also wears the brand.
            word = theme_hex.lower()
            if word == "blue": theme_hex = "#007aff"
            elif word == "green": theme_hex = cls.GREEN
            elif word == "red": theme_hex = cls.RED
            elif word == "ice": theme_hex = "#38e1ff"
            elif word in ("gold", "aurum", "amber", "saturn", "cyberpunk", "magenta"):
                theme_hex = cls.GOLD
            elif word == "violet": theme_hex = cls.GOLD_MID
            else: theme_hex = cls.GOLD

        # The retired Aurum gold identity is gone, but a config saved before the
        # rebrand still carries a gold accent hex. Any of those legacy values is
        # read as "the old brand", which now means the cyberpunk accent, so a
        # stale app_theme can never repaint the shell gold.
        _LEGACY_GOLD = {"#ffc857", "#ff8a1f", "#fff3d6", "#ff9f1c", "#ffe08a",
                        "#d9a83f", "#1a0e00", "#f5ebd8"}
        if theme_hex.lower() in _LEGACY_GOLD:
            theme_hex = cls.GOLD

        # The curated cyberpunk palette on the class body is the brand truth: a
        # magenta accent living on purple surfaces with a purple hairline border.
        # The generic derivation below builds *every* surface colour from one
        # accent hex, which would tint borders and glass magenta and drift away
        # from the design - so for the brand accent we keep the curated tokens and
        # only re-polish the shell by firing the listeners.
        if theme_hex.lower() == cls.GOLD.lower():
            for cb in list(cls._listeners):
                try:
                    cb()
                except Exception:
                    pass
            return

        import colorsys
        try:
            r = int(theme_hex[1:3], 16)
            g = int(theme_hex[3:5], 16)
            b = int(theme_hex[5:7], 16)
        except Exception:
            r, g, b = 255, 255, 255
            theme_hex = "#ffffff"
            
        h, l, s = colorsys.rgb_to_hls(r/255.0, g/255.0, b/255.0)
        
        # Dim (darker by reducing l by 15%)
        l_dim = max(0.0, l - 0.15)
        r_dim, g_dim, b_dim = colorsys.hls_to_rgb(h, l_dim, s)
        hex_dim = f"#{int(r_dim*255):02x}{int(g_dim*255):02x}{int(b_dim*255):02x}"
        
        # Acc2 (lighter by increasing l by 15%)
        l_light = min(1.0, l + 0.15)
        r_light, g_light, b_light = colorsys.hls_to_rgb(h, l_light, s)
        hex_light = f"#{int(r_light*255):02x}{int(g_light*255):02x}{int(b_light*255):02x}"

        # A white/near-white theme means "no accent chosen" and wears the brand
        # accent rather than snapping to a legibility fallback.
        plain = {"#ffffff", "#f3edff", "#f4f6f8", "#e2e8f0"}
        cls.PRI       = theme_hex
        cls.PRI_DIM   = hex_dim
        cls.PRI_GHO   = f"rgba({r}, {g}, {b}, 0.15)"
        cls.ACC       = cls.GOLD if theme_hex.lower() in plain else theme_hex
        cls.ACC2      = cls.S_LISTEN[0] if theme_hex.lower() in plain else hex_light
        cls.MUTED_C   = cls.GOLD if theme_hex.lower() in plain else theme_hex
        cls.BORDER    = f"rgba({r}, {g}, {b}, 0.17)"
        cls.BORDER_B  = f"rgba({r}, {g}, {b}, 0.35)"
        cls.BORDER_A  = f"rgba({r}, {g}, {b}, 0.20)"
        # Any custom accent gradient-stops down to its own dim, so a violet theme
        # still reads as violet on a filled button.
        cls.PRI_GRAD    = hex_dim
        cls.GLASS       = f"rgba({r}, {g}, {b}, 0.07)"
        cls.GLASS_BRIGHT = f"rgba({r}, {g}, {b}, 0.09)"
        cls.BUBBLE_EDGE  = f"rgba({r}, {g}, {b}, 0.22)"

        for cb in list(cls._listeners):
            try:
                cb()
            except Exception:
                pass

    # Theme mode. The delivered design ships one dark and one light token set
    # (tokens.md / saturn_command.html :root[data-theme]); everything else about
    # the shell - geometry, type, the chamfer - is identical. A flip re-copies the
    # chosen set onto the live C.* attributes and re-polishes through the same
    # listener fan-out the accent picker already uses, so every registered widget
    # rebuilds its stylesheet from the new values.
    THEME = "dark"

    _DARK_TOKENS = {
        "BG": "#05030A", "EMBER": "#1A0A26", "PANEL": "#0D0716", "PANEL2": "#1A0A26",
        "BORDER": "rgba(58, 33, 82, 0.85)", "BORDER_B": "rgba(255, 43, 214, 0.45)",
        "BORDER_A": "rgba(243, 237, 255, 0.16)",
        "GOLD": "#FF2BD6", "GOLD_DEEP": "#C2009E", "GOLD_LT": "#F3EDFF", "GOLD_MID": "#9B5CFF",
        "ON_GOLD": "#0D0716", "ACC": "#FF2BD6", "ACC2": "#F5E94B", "GREEN": "#B6FF3B",
        "GREEN_D": "#3F7D00", "RED": "#FF2B4A", "TEXT": "#F3EDFF", "TEXT_DIM": "#9A8FB5",
        "TEXT_MED": "#C9C2DC", "WHITE": "#F3EDFF", "DARK": "#0D0716", "BAR_BG": "#0D0716",
        "UNSET": "#6E6A7C",
        "PRI": "#FF2BD6", "PRI_DIM": "#C2009E", "PRI_GHO": "rgba(255, 43, 214, 0.12)",
        "PRI_GRAD": "#9B5CFF", "GLASS": "rgba(255, 43, 214, 0.06)",
        "GLASS_BRIGHT": "rgba(255, 43, 214, 0.09)", "BUBBLE_EDGE": "rgba(255, 43, 214, 0.24)",
        "ICE": "#FF2BD6", "ICE_DIM": "#C2009E", "ICE_GHO": "rgba(255, 43, 214, 0.15)",
        "MUTED_C": "#FF2BD6",
    }
    _LIGHT_TOKENS = {
        "BG": "#F6F1FB", "EMBER": "#EDE4F7", "PANEL": "#FFFFFF", "PANEL2": "#EDE4F7",
        "BORDER": "rgba(214, 200, 232, 0.95)", "BORDER_B": "rgba(194, 0, 158, 0.40)",
        "BORDER_A": "rgba(26, 16, 36, 0.14)",
        "GOLD": "#C2009E", "GOLD_DEEP": "#8A0070", "GOLD_LT": "#1A1024", "GOLD_MID": "#6A2FD0",
        "ON_GOLD": "#FFFFFF", "ACC": "#C2009E", "ACC2": "#8A7A00", "GREEN": "#3F7D00",
        "GREEN_D": "#2C5900", "RED": "#D0102E", "TEXT": "#1A1024", "TEXT_DIM": "#5E5275",
        "TEXT_MED": "#413855", "WHITE": "#1A1024", "DARK": "#FFFFFF", "BAR_BG": "#FFFFFF",
        "UNSET": "#6E6A7C",
        "PRI": "#C2009E", "PRI_DIM": "#8A0070", "PRI_GHO": "rgba(194, 0, 158, 0.10)",
        "PRI_GRAD": "#6A2FD0", "GLASS": "rgba(194, 0, 158, 0.05)",
        "GLASS_BRIGHT": "rgba(194, 0, 158, 0.08)", "BUBBLE_EDGE": "rgba(194, 0, 158, 0.22)",
        "ICE": "#C2009E", "ICE_DIM": "#8A0070", "ICE_GHO": "rgba(194, 0, 158, 0.12)",
        "MUTED_C": "#C2009E",
    }

    @classmethod
    def apply_mode(cls, mode: str) -> None:
        mode = "light" if str(mode or "").lower() == "light" else "dark"
        cls.THEME = mode
        table = cls._LIGHT_TOKENS if mode == "light" else cls._DARK_TOKENS
        for key, val in table.items():
            setattr(cls, key, val)
        # PRI tracks the brand accent so any code that still reads C.PRI follows.
        cls.PRI = cls.GOLD
        for cb in list(cls._listeners):
            try:
                cb()
            except Exception:
                pass
        for fn in list(_THEME_REAPPLY):
            try:
                fn()
            except Exception:
                pass

    @classmethod
    def is_light(cls) -> bool:
        return cls.THEME == "light"


