    def _summary_html(self) -> str:
        parts = []
        for i, (txt, _) in enumerate(self._sents):
            if self._playing and i == self._play_i:
                parts.append(
                    f'<span style="background:{C.HI}; color:{C.TEXT};">{_html_esc(txt)} </span>')
            else:
                parts.append(_html_esc(txt) + " ")
        return "".join(parts)

