        self.setMinimumHeight(1)
        max_w = 340
        if parent and hasattr(parent, "viewport"):
            max_w = max(200, int(parent.viewport().width() * 0.84))
        self.setMaximumWidth(max_w)
        if role == "user":
            self.setMinimumWidth(120)

        bg_style = S.bubble(role == "user")
        # A gold-filled bubble needs ink the other way round, or the user's own
        # words disappear into the fill.
        self._ink = C.ON_GOLD if role == "user" else C.TEXT
        self._ink_soft = "rgba(13, 7, 22, 0.62)" if role == "user" else "rgba(243, 237, 255, 0.45)"
