    def apply_theme(self):
        pri = getattr(C, "PRI", "#FF2BD6") or "#FF2BD6"
        try:
            r = int(pri[1:3], 16)
            g = int(pri[3:5], 16)
            b = int(pri[5:7], 16)
        except Exception:
            pri = "#FF2BD6"
            r, g, b = 255, 43, 214

