        intro_lay.setContentsMargins(0, 0, 0, 0)
        intro_lay.setSpacing(12)

        self._intro_lines = []
        for txt in ["Identity confirmed.", "Hello.", "I'm Saturn.", "Ready whenever you are."]:
            lbl = QLabel(txt)
            lbl.setAlignment(Qt.AlignmentFlag.AlignCenter)
            if txt == "I'm Saturn.":
                lbl.setFont(QFont(C.F_BODY, 24, QFont.Weight.Bold))
                lbl.setStyleSheet("color: #FF2BD6; background: transparent; border: none;")
            else:
                lbl.setFont(QFont(C.F_BODY, 14))
                lbl.setStyleSheet("color: rgba(255,255,255,0.6); background: transparent; border: none;")
