        # left: narration
        narr = QFrame()
        narr.setObjectName("panel")
        nlay = QVBoxLayout(narr)
        nlay.setContentsMargins(16, 16, 16, 16)
        nlay.setSpacing(8)
        self._narr_lab = QLabel("SATURN SPEAKING\u2026")
        self._narr_lab.setObjectName("narrLab")
        self._narr_wl = _SetupWaveBars(n=40, right=True)
        self._narr_title = QLabel("")
        self._narr_title.setObjectName("narrTitle")
        self._narr_title.setTextFormat(Qt.TextFormat.RichText)
        self._narr_title.setWordWrap(True)
        self._narr_body = QLabel("")
        self._narr_body.setObjectName("narrBody")
        self._narr_body.setWordWrap(True)
        self._narr_body.setMinimumHeight(96)
        self._narr_body.setAlignment(Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft)
        nlay.addWidget(self._narr_lab)
        nlay.addWidget(self._narr_wl)
        nlay.addWidget(self._narr_title)
        nlay.addWidget(self._narr_body, 1)
        grid.addWidget(narr, 1, 0)

        # centre: orb
        orbbox = QVBoxLayout()
        orbbox.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._orb = _SetupOrb(430)
        self._orb.set_reduce(self._reduce)
        self._orb.set_state("idle")
        orbbox.addWidget(self._orb, 0, Qt.AlignmentFlag.AlignCenter)
        grid.addLayout(orbbox, 1, 1)

        # right: accordion
        rp = QFrame()
        rp.setObjectName("rpPanel")
        rlay = QVBoxLayout(rp)
        rlay.setContentsMargins(16, 14, 16, 14)
        rlay.setSpacing(6)
        head = QHBoxLayout()
        h1 = QLabel("FIRST-TIME SETUP")
        h1.setObjectName("rpHead")
        self._step_count = QLabel("STEP 1 OF 6")
        self._step_count.setObjectName("stepSub")
        head.addWidget(h1)
        head.addStretch(1)
        head.addWidget(self._step_count)
        rlay.addLayout(head)
        rsub = QLabel("Let\u2019s get Saturn ready for your PC. This appears only the first time.")
        rsub.setObjectName("rpSub")
        rsub.setWordWrap(True)
        rlay.addWidget(rsub)
        self._acc = QVBoxLayout()
        self._acc.setSpacing(2)
        self._build_steps()
        rlay.addLayout(self._acc, 1)
        grid.addWidget(rp, 1, 2)

        # bottom row
        clk = QFrame()
        clk.setObjectName("panel")
        clay = QVBoxLayout(clk)
        clay.setContentsMargins(16, 10, 16, 10)
        self._clk_t = QLabel("--:--")
        self._clk_t.setObjectName("clockT")
        self._clk_d = QLabel("")
        self._clk_d.setObjectName("clockD")
        clay.addWidget(self._clk_t)
        clay.addWidget(self._clk_d)
        grid.addWidget(clk, 2, 0)

        ctl = QWidget()
        clay2 = QVBoxLayout(ctl)
        clay2.setContentsMargins(0, 0, 0, 0)
        row = QHBoxLayout()
        row.setSpacing(10)
        self._btn_mute = QPushButton("Mute")
        self._btn_mute.setCheckable(True)
        self._btn_mute.setProperty("role", "round")
        self._btn_mute.clicked.connect(self._toggle_mute)
        self._wa = _SetupWaveBars(n=16, right=False)
        self._btn_mic = QPushButton("Mic")
        self._btn_mic.setCheckable(True)
        self._btn_mic.setProperty("role", "round")
        self._btn_mic.setFixedSize(72, 72)
        self._btn_mic.clicked.connect(self._toggle_mic)
        self._wb = _SetupWaveBars(n=16, right=True)
        self._btn_replay = QPushButton("Replay")
        self._btn_replay.clicked.connect(lambda: self._say(self._cur))
        row.addStretch(1)
        row.addWidget(self._btn_mute)
        row.addWidget(self._wa)
        row.addWidget(self._btn_mic)
        row.addWidget(self._wb)
        row.addWidget(self._btn_replay)
        row.addStretch(1)
        clay2.addLayout(row)
        self._lis = QLabel("Say \u201cnext\u201d to continue")
        self._lis.setObjectName("lis")
        self._lis.setAlignment(Qt.AlignmentFlag.AlignCenter)
        clay2.addWidget(self._lis)
        self._dots = QLabel("")
        self._dots.setAlignment(Qt.AlignmentFlag.AlignCenter)
        self._dots.setStyleSheet(f"color:{C.TEXT_DIM}; letter-spacing:6px;")
        self._dot_on = 0
        self._tick_dots()
        clay2.addWidget(self._dots)
        grid.addWidget(ctl, 2, 1)

        quote = QFrame()
        quote.setObjectName("panel")
        qlay = QVBoxLayout(quote)
        qlay.setContentsMargins(16, 12, 16, 12)
