        self._dnd_notice.setFont(QFont(C.F_BODY, 9))
        self._dnd_notice.setWordWrap(True)
        self._dnd_notice.setStyleSheet(
            f"color: {C.ACC2}; border: 1px solid {C.ACC2}; background: transparent;"
            f" padding: 6px 10px; margin: 8px 12px 0 12px;"
        )
        self._dnd_notice.hide()
        root.addWidget(self._dnd_notice)

        # Filter row
        self._filter_bar = QFrame()
        self._filter_bar.setStyleSheet(f"background: transparent; border-bottom: 1px solid {C.BORDER};")
        fl = QHBoxLayout(self._filter_bar)
        fl.setContentsMargins(12, 6, 12, 6)
        fl.setSpacing(6)
        self._filter_btns: list[QPushButton] = []
        self._current_filter = "all"
        for fk, fl_lbl in [("all", "All"), ("unread", "Unread"), ("reminders", "Reminders"),
                           ("mail", "Mail"), ("devices", "Devices"), ("system", "System")]:
            b = QPushButton(fl_lbl)
            b.setCheckable(True)
            b.setFixedHeight(22)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
