    def _toggle_mute(self):
        self._muted = not self._muted
        # A manual pause is absolute: the mic pipeline goes fully quiet (the
        # engine feeds the duplex silence) and nothing heard while paused can
        # re-open the ears. Only this button resumes.
        self._wakeword_listening = False
        self._muted_ui_exempt = False
        self.hud.muted = self._muted
        self._style_mute_btn()
        if hasattr(self, "_taskbar_waveform") and self._taskbar_waveform:
            self._taskbar_waveform.set_muted(self._muted)
        if self._muted:
            self._apply_state("MUTED")
            self._log.append_log("SYS: Microphone muted.")
            sound_mgr.play_mute(True)
        else:
            self._apply_state("LISTENING")
            self._log.append_log("SYS: Microphone active.")
            sound_mgr.play_mute(False)

    def set_muted_state(self, muted: bool, *, wakeword: bool = False):
        muted = bool(muted)
        if muted == self._muted and not wakeword:
            return
        self._muted = muted
        self.hud.muted = self._muted
        self._wakeword_listening = False
        self._muted_ui_exempt = False
        self._style_mute_btn()
        if hasattr(self, "_taskbar_waveform") and self._taskbar_waveform:
            self._taskbar_waveform.set_muted(self._muted)
        if self._muted:
            self._apply_state("MUTED")
            self._log.append_log("SYS: Microphone muted.")
            sound_mgr.play_mute(True)
        else:
            self._apply_state("LISTENING")
            self._log.append_log("SYS: Microphone active.")
            sound_mgr.play_mute(False)

    def _style_mute_btn(self):
        if not hasattr(self, "_mute_btn") or self._mute_btn is None:
            return
        if self._muted:
            self._mute_btn.setText("Muted")
            self._mute_btn.setStyleSheet(f"""
                QPushButton {{
                    background: #0D0716; color: {C.RED};
                    border: 1px solid {C.RED}; border-radius: 0px;
                }}
            """)
        else:
            self._mute_btn.setText("Mic")
            self._mute_btn.setStyleSheet(f"""
                QPushButton {{
                    background: rgba(13, 7, 22,235); color: {C.WHITE};
                    border: 1px solid {C.BORDER_B}; border-radius: 0px;
                }}
                QPushButton:hover {{ border: 1px solid {C.WHITE}; }}
            """)

    def _send(self, txt: str = ""):
        if not txt:
            txt = self._input.text().strip()
            self._input.clear()
        if not txt:
            return
        self.submit_command(txt)

    def submit_command(self, txt: str, source: str = "local"):
        txt = (txt or "").strip()
        if not txt:
            return
        # Typing is a deliberate interaction, so this one turn may repaint the
        # mic states while the mic itself stays paused (answering a typed
        # command while paused is legitimate). Cleared on every mute change.
        self._muted_ui_exempt = True
        # May be called from a Discord/remote thread. Emit instead of mutating
        # widgets here; the queued slot runs this on the GUI thread.
        self._submit_command_sig.emit(txt, source or "local")

    def _do_submit_command(self, txt: str, source: str = "local"):
        self._chat_source_queue.append(source or "local")
        if hasattr(self, "_command_card"):
            preview = txt[:60] + ("…" if len(txt) > 60 else "")
            self._command_card.set_body(preview)
            self._command_card.hide()
        if hasattr(self, "_result_card"):
            self._result_card.set_body("Waiting for reply...")
            self._result_card.hide()
        self._restart_card_hide_timer()
        self._log_sig.emit(f"You: {txt}")
        if self.on_text_command:
            threading.Thread(target=self.on_text_command, args=(txt, source or "local"), daemon=True).start()

    def _on_log_text(self, text: str):
        self._log.append_log(text)
        raw = (text or "").strip()
        low = raw.lower()
        self._feed_conversation(low, raw)
        if hasattr(self, "_result_card") and low.startswith("you:"):
            user_msg = raw.split(":", 1)[1].strip()
            source = self._chat_source_queue[0] if self._chat_source_queue else "local"
            if self.on_chat_event and user_msg:
                try:
                    self.on_chat_event({"role": "user", "text": user_msg, "source": source})
                except Exception:
                    pass
        if hasattr(self, "_result_card") and low.startswith("saturn:"):
            reply = raw.split(":", 1)[1].strip()
            self._result_card.set_body(reply[:80] + ("…" if len(reply) > 80 else ""))
            self._result_card.hide()
            self._restart_card_hide_timer()
            source = self._chat_source_queue[0] if self._chat_source_queue else "local"
            if self.on_chat_event and reply:
                try:
                    self.on_chat_event({"role": "assistant", "text": reply, "source": source})
                except Exception:
                    pass
            if self._chat_source_queue:
                self._chat_source_queue.popleft()
        elif hasattr(self, "_result_card") and low.startswith("err:"):
            self._result_card.set_body(raw.split(":", 1)[1].strip())
            self._result_card.hide()
            self._restart_card_hide_timer()
            source = self._chat_source_queue[0] if self._chat_source_queue else "local"
            if self.on_chat_event:
                try:
                    self.on_chat_event({"role": "system", "text": raw.split(":", 1)[1].strip(), "source": source})
                except Exception:
                    pass
            if self._chat_source_queue:
                self._chat_source_queue.popleft()

    def _feed_conversation(self, low: str, raw: str) -> None:
        """Mirror the engine's log funnel into the ``.feed``.

        ``_log_sig`` already carries every user line, Saturn reply and error, so
        the feed is driven from this one place rather than from each entry point
        (composer, voice, Discord, remote). The 'You' line opens a thinking state
        and the typing placeholder; the reply or error replaces it - the mockup's
        ``mk()`` + ``reply()`` pair.
        """
        conv = getattr(self, "_conversation", None)
        if conv is None:
            return
        try:
            if low.startswith("you:"):
                msg = raw.split(":", 1)[1].strip()
                if not msg:
                    return
                src = self._chat_source_queue[0] if self._chat_source_queue else "local"
                conv.add_user(msg, tag="voice" if "voice" in src or "mic" in src else None)
                conv.add_typing()
                conv.set_state("thinking")
                conv.set_subtitle("Working on it\u2026")
            elif low.startswith("saturn:"):
                conv.remove_typing()
                reply = raw.split(":", 1)[1].strip()
                if reply:
                    conv.add_assistant(reply)
            elif low.startswith("err:"):
                conv.remove_typing()
                conv.add_assistant("", error=raw.split(":", 1)[1].strip())
        except Exception:
            pass

    def _restart_card_hide_timer(self):
        if hasattr(self, "_card_hide_tmr"):
            self._card_hide_tmr.start(5000)

    def _hide_command_cards(self):
        if hasattr(self, "_command_card"):
            self._command_card.hide()
        if hasattr(self, "_result_card"):
            self._result_card.hide()
        if hasattr(self, "_hud_result_wing"):
            self._hud_result_wing.dismiss()
        if hasattr(self, "_hud_telemetry_wing"):
            self._hud_telemetry_wing.dismiss()

