    def _apply_confirm_overlay(self, action: str, title: str = "", detail: str = ""):
        if action == "hide":
            if getattr(self, "_confirm_overlay", None):
                try:
                    self._confirm_overlay.deleteLater()
                except Exception:
                    pass
                self._confirm_overlay = None
            return

        if action == "show":
            if getattr(self, "_confirm_overlay", None):
                try:
                    self._confirm_overlay.deleteLater()
                except Exception:
                    pass
                self._confirm_overlay = None

            overlay = ConfirmationOverlay(title, detail, parent=self)
            overlay.answered.connect(self._on_confirm_answered)
            overlay.closed.connect(lambda: setattr(self, "_confirm_overlay", None))
            self._confirm_overlay = overlay
            self._position_confirm_overlay()
            overlay.show()
            overlay.raise_()

            try:
                from sound_manager import sound_mgr
                sound_mgr.play_sfx("telemetry_chirp")
            except Exception:
                pass

    def _apply_saturn_malfunction(self, payload: dict):
        action = (payload.get("action") or "show").lower()
        if action in ("close", "hide"):
            if getattr(self, "_saturn_dialog", None):
                try:
                    self._saturn_dialog.close()
                except Exception:
                    pass
                self._saturn_dialog = None
            return

        if getattr(self, "_saturn_dialog", None) is None or not self._saturn_dialog.isVisible():
            self._saturn_dialog = SaturnMalfunctionDialog(payload, parent=None)
            screen = QApplication.primaryScreen().availableGeometry()
            self._saturn_dialog.adjustSize()
            x = max(24, screen.right() - self._saturn_dialog.width() - 28)
            y = screen.top() + 36
            self._saturn_dialog.move(x, y)
            self._saturn_dialog.show()
            self._saturn_dialog.raise_()
            self._saturn_dialog.activateWindow()
        else:
            self._saturn_dialog.update_content(payload)
            self._saturn_dialog.show()
            self._saturn_dialog.raise_()

