    def _apply_memory_overlay(self, action: str):
        """Memory is a Command Center section, not a dialog (mockup body.mv):
        ``show`` swaps the centre stack to the Memory page, ``hide`` returns to
        the Command Home. The orb is suppressed for every non-home index by
        ``_on_center_page`` exactly like Devices or Settings, so it can never
        float over the page the way the old popup did."""
        if not hasattr(self, "_center_stack"):
            return
        if action == "hide":
            if self._center_stack.currentIndex() == _PAGE_MEMORY:
                self._center_stack.setCurrentIndex(0)
            return
        page = getattr(self, "_memory_page", None)
        if page is not None:
            try:
                page._refresh()
            except Exception:
                pass
        self._center_stack.setCurrentIndex(_PAGE_MEMORY)

