        class _HudShim:
            def __init__(self):
                self.state = "ONLINE"
                self.speaking = False
                self.listening = False
                self.muted = False
            def set_state(self, s): self.state = s
            def set_audio_level(self, lvl): pass
            def feed_level(self, lvl): pass
            def update(self): pass
            def repaint(self): pass
            def show(self): pass
            def hide(self): pass
            def isVisible(self): return False
            def setVisible(self, v): pass
            def __getattr__(self, name):
                return lambda *args, **kwargs: None
        self.hud = _HudShim()

        # ── Command Home (Phase E) ────────────────────────────────────────────
        # quote + subsystem line at the top, the orb stage (a transparent spacer
        # the web orb paints behind, targeted by _reposition_orb) in the middle,
        # then the subtitle bar, the composer and the capability tiles below. The
