        hc_hdr = QHBoxLayout()
        hc_title = QLabel("All systems healthy")
        hc_title.setFont(QFont(C.F_BODY, 12, QFont.Weight.Bold))
        hc_title.setStyleSheet(f"color: {C.TEXT}; background: transparent; border: none;")
        hc_hdr.addWidget(hc_title)
        hc_hdr.addStretch(1)
        self._health_pill = self._make_pill("AUTO-HEAL ON", "ok")
        hc_hdr.addWidget(self._health_pill)
        hc_lay.addLayout(hc_hdr)
        hc_desc = QLabel("No faults detected. Saturn checks its own parts every minute and fixes problems on this PC.")
        hc_desc.setFont(QFont(C.F_BODY, 10))
        hc_desc.setWordWrap(True)
        hc_desc.setStyleSheet(f"color: {C.TEXT_DIM}; background: transparent; border: none;")
        hc_lay.addWidget(hc_desc)
        right_lay.addWidget(self._health_card)

        # Fault card (hidden initially)
        self._fault_card = QFrame()
        self._fault_card.setObjectName("FaultCard")
        self._fault_card.setStyleSheet(self._card_style())
        self._fault_card.hide()
        self._fault_lay = QVBoxLayout(self._fault_card)
        self._fault_lay.setContentsMargins(12, 10, 12, 10)
        self._fault_lay.setSpacing(6)
        right_lay.addWidget(self._fault_card)

        # Patch card (hidden initially)
        self._patch_card = QFrame()
        self._patch_card.setObjectName("PatchCard")
        self._patch_card.setStyleSheet(self._card_style())
        self._patch_card.hide()
        self._patch_lay = QVBoxLayout(self._patch_card)
        self._patch_lay.setContentsMargins(12, 10, 12, 10)
        self._patch_lay.setSpacing(6)
        right_lay.addWidget(self._patch_card)

        # Repair log
        log_card = QFrame()
        log_card.setObjectName("LogCard")
        log_card.setStyleSheet(self._card_style())
        lc_lay = QVBoxLayout(log_card)
        lc_lay.setContentsMargins(12, 10, 12, 10)
        lc_lay.setSpacing(6)
        lc_hdr = QLabel("Repair log")
        lc_hdr.setFont(QFont(C.F_BODY, 12, QFont.Weight.Bold))
        lc_hdr.setStyleSheet(f"color: {C.TEXT}; background: transparent; border: none;")
        lc_lay.addWidget(lc_hdr)
        self._log_area = QPlainTextEdit()
        self._log_area.setReadOnly(True)
        self._log_area.setMaximumHeight(150)
        self._log_area.setFont(QFont(C.F_MONO, 10))
        self._log_area.setStyleSheet(
            f"QPlainTextEdit {{ background: {C.HI}; color: {C.TEXT_DIM};"
            f" border: 1px solid {C.BORDER}; border-radius: 0; padding: 8px; }}"
        )
        self._log_area.setPlainText("Waiting for a fault\u2026")
        lc_lay.addWidget(self._log_area)
