        self.setObjectName("SystemConnectivityPage")
        # One sheet for the whole screen. The cards, pills, wells and dropdowns
        # below inherit from here, so a theme change reaches all of them; each
        # used to carry its own hand-copied gold, which is why some of them
        # repainted when the brand moved and others did not.
        self.setStyleSheet(S.settings_sheet("QWidget#SystemConnectivityPage") + f"""
            QMessageBox, QDialog {{
                background-color: {C.PANEL};
                color: {C.TEXT};
                border: 1px solid {C.BORDER_B};
                border-radius: 0px;
            }}
            QMessageBox QLabel, QDialog QLabel {{
                color: {C.TEXT};
                background-color: transparent;
                font-size: 13px;
                padding: 4px;
            }}
        """ + f"""
            QMessageBox QPushButton, QDialog QPushButton {{
                background-color: {C.PRI};
                color: {C.ON_GOLD};
                font-weight: 700;
                font-size: 12px;
                border: none;
                border-radius: 0px;
                padding: 8px 24px;
                min-width: 80px;
                min-height: 30px;
            }}
            QMessageBox QPushButton:hover, QDialog QPushButton:hover {{
                background-color: {C.ACC2};
            }}
            QMessageBox QPushButton:pressed, QDialog QPushButton:pressed {{
                background-color: {C.PRI_DIM};
            }}
        """)
        root = QVBoxLayout(self)
        root.setContentsMargins(18, 16, 18, 16)
        root.setSpacing(0)

        self._scroll = QScrollArea()
        self._scroll.setFrameShape(QFrame.Shape.NoFrame)
        self._scroll.setWidgetResizable(True)
        self._scroll.setStyleSheet("QScrollArea { background: transparent; border: none; }")
        root.addWidget(self._scroll)

        self._content = QWidget()
        self._scroll.setWidget(self._content)
        lay = QVBoxLayout(self._content)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(16)

        header = QFrame()
        header.setStyleSheet("background: transparent; border: none;")
        h_lay = QVBoxLayout(header)
        h_lay.setContentsMargins(0, 0, 0, 0)
        h_lay.setSpacing(6)
        title = QLabel("System & Connectivity")
        title.setStyleSheet(S.display(24, 600, 1))
        sub = QLabel("Manage your AI providers, connections and application preferences.")
        sub.setStyleSheet(f"color: {C.TEXT_DIM}; font-size: 13px; background: transparent;")
        h_lay.addWidget(title)
        h_lay.addWidget(sub)
