    def _build_security_card(self):
        card = self._card(
            "Security Perimeter",
            "The camera watches the desk. It locks the workstation only when someone "
            "it cannot verify arrives after you have left - never while the camera is "
            "faulty, never on a single frame, and never without asking you first.",
        )
        lay = card.layout()

        self._sec_status_lbl = QLabel("Status: checking...")
        self._sec_status_lbl.setWordWrap(True)
        self._sec_status_lbl.setStyleSheet(
            f"color: {C.TEXT_DIM}; font-size: 11px; font-weight: bold;")
        lay.addWidget(self._sec_status_lbl)

        self._sec_arm_start_btn = self._mk_toggle(
            "Arm automatically when Saturn starts", False, self._set_arm_on_start)
        lay.addWidget(self._sec_arm_start_btn)

        self._sec_enabled_btn = self._mk_toggle(
            "Watch the desk and report camera faults", True, self._set_perimeter_enabled)
        lay.addWidget(self._sec_enabled_btn)

        self._sec_dry_run_btn = self._mk_toggle(
            "Dry run - record the decision, never lock", True, self._set_perimeter_dry_run)
        lay.addWidget(self._sec_dry_run_btn)

        row = QHBoxLayout()
        row.setSpacing(10)
        self._sec_arm_btn = QPushButton("Arm now")
        self._sec_arm_btn.clicked.connect(self._arm_perimeter_now)
        row.addWidget(self._sec_arm_btn)
        self._sec_disarm_btn = QPushButton("Disarm")
        self._sec_disarm_btn.clicked.connect(self._disarm_perimeter_now)
        row.addWidget(self._sec_disarm_btn)
        self._sec_pass_btn = QPushButton("Set passphrase")
        self._sec_pass_btn.clicked.connect(self._open_perimeter_passphrase)
        row.addWidget(self._sec_pass_btn)
        lay.addLayout(row)

        hint = QLabel(
            "Arming needs an enrolled face, the face models, a passphrase and a "
            "working camera. If any of those is missing I will say which one, and "
            "stay unarmed rather than pretend.")
        hint.setWordWrap(True)
        hint.setStyleSheet(f"color: {C.TEXT_DIM}; font-size: 10px;")
        lay.addWidget(hint)

        self._refresh_security_card()
        return card

    # ── Security perimeter ────────────────────────────────────────────

    def _perimeter(self):
        from core.security_perimeter import get_perimeter

        return get_perimeter()

    def _sec_say(self, text: str):
        """Say it on the card and in the log - the two places it will be read."""
        if hasattr(self, "_sec_status_lbl"):
            self._sec_status_lbl.setText(text)
        ctrl = self._ctrl()
        if ctrl is not None and hasattr(ctrl, "write_log"):
            try:
                ctrl.write_log(f"SEC: {text}")
            except Exception:
                pass

    @staticmethod
    def _perimeter_is_watching() -> bool:
        try:
            from core.presence_watch import get_presence_watcher

            return bool(get_presence_watcher().running)
        except Exception:
            return False

    def _refresh_security_card(self):
        if not hasattr(self, "_sec_status_lbl"):
            return
        try:
            from core import passphrase_vault
            from core.security_perimeter import load_config

            config = load_config()
            passphrase = passphrase_vault.configured()
        except Exception as exc:
            self._sec_status_lbl.setText(f"Status: unavailable ({exc})")
            return
        self._sec_status_lbl.setText(
            "Status: "
            + ("armed" if config.get("armed") else "not armed")
            + (", watching" if self._perimeter_is_watching() else ", not running")
            + (", passphrase set." if passphrase else ", no passphrase set."))
        for button, key, default in (
            (getattr(self, "_sec_arm_start_btn", None), "arm_on_start", True),
            (getattr(self, "_sec_enabled_btn", None), "enabled", True),
            (getattr(self, "_sec_dry_run_btn", None), "dry_run", True),
        ):
            if button is not None:
                button.blockSignals(True)
                button.setChecked(bool(config.get(key, default)))
                button.blockSignals(False)

    def _save_perimeter_setting(self, patch: dict):
        try:
            from core.security_perimeter import save_config

            save_config(patch)
        except Exception as exc:
            self._sec_say(f"Could not save that setting: {exc}")
            return
        self._refresh_security_card()

    def _set_arm_on_start(self, checked: bool):
        self._save_perimeter_setting({"arm_on_start": bool(checked)})
        self._sec_say("The perimeter will arm itself at every start." if checked else
                      "The perimeter will not arm itself; it waits to be asked.")

    def _set_perimeter_enabled(self, checked: bool):
        self._save_perimeter_setting({"enabled": bool(checked)})
        self._sec_say("The perimeter is switched on." if checked else
                      "The perimeter is switched off - it will not sample the camera "
                      "or report faults.")

    def _set_perimeter_dry_run(self, checked: bool):
        self._save_perimeter_setting({"dry_run": bool(checked)})
        self._sec_say("Dry run is on: the perimeter records what it would do." if checked
                      else "Dry run is off: the perimeter may now lock the workstation.")

    def _arm_perimeter_now(self):
        # The self-test opens the camera, so let the button finish drawing first
        # rather than freezing the window for the length of a probe.
        self._sec_say("Arming... checking the camera, the face models and the passphrase.")
        QTimer.singleShot(0, self._arm_perimeter_blocking)

    def _arm_perimeter_blocking(self):
        try:
            result = self._perimeter().arm()
        except Exception as exc:
            self._sec_say(f"Arming failed: {exc}")
            return
        if result.get("ok"):
            self._sec_say(str(result.get("message") or "Armed."))
        else:
            problems = result.get("problems") or [result.get("message") or "unknown reason"]
            self._sec_say("Not armed. " + " ".join(str(problem) for problem in problems))
        self._refresh_security_card()

    def _disarm_perimeter_now(self):
        try:
            from core import passphrase_vault

            guarded = bool(passphrase_vault.configured())
        except Exception:
            guarded = True
        if not guarded:
            self._disarm_perimeter()
            return
        ask = getattr(self.window(), "ask_passphrase", None)
        if ask is None:
            self._sec_say("I cannot disarm it from here: there is no prompt to check "
                          "a passphrase with.")
            return
        self._sec_say("Waiting for the passphrase...")
        ask("Confirm the passphrase to disarm the security perimeter.",
            self._on_disarm_passphrase, mode="ask")

    def _on_disarm_passphrase(self, text):
        if not text:
            self._sec_say("Disarming cancelled.")
            return
        try:
            from core import passphrase_vault

            matched = bool(passphrase_vault.check_passphrase(text))
        except Exception:
            matched = False
        if not matched:
            self._sec_say("That passphrase did not match, so the perimeter stays armed.")
            return
        self._disarm_perimeter()

    def _disarm_perimeter(self):
        try:
            result = self._perimeter().disarm()
        except Exception as exc:
            self._sec_say(f"Could not disarm: {exc}")
            return
        self._sec_say(str(result.get("message") or "Disarmed."))
        self._refresh_security_card()

    def _open_perimeter_passphrase(self):
        ask = getattr(self.window(), "ask_passphrase", None)
        if ask is None:
            self._sec_say("There is no prompt available to set a passphrase.")
            return
        ask("Choose the passphrase that unlocks the perimeter when the camera "
            "cannot confirm who is at the desk.",
            self._on_new_perimeter_passphrase, mode="new")

    def _on_new_perimeter_passphrase(self, text):
        if not text:
            self._sec_say("Passphrase not set.")
            return
        try:
            from core import passphrase_vault

            result = passphrase_vault.set_passphrase(text)
        except Exception as exc:
            self._sec_say(f"Could not save the passphrase: {exc}")
            return
        if result.get("ok"):
            self._sec_say("Passphrase set. Arming is possible now.")
        else:
            self._sec_say(str(result.get("message") or "The passphrase was not saved."))
        self._refresh_security_card()

