    def notify(self, type_key: str, title: str, body: str, actions: tuple = ("Dismiss",)):
        """Push a notification through the engine's UI bridge."""
        mgr = getattr(self._win, "_notif_mgr", None)
        if mgr is not None:
            # Thread-safe: queue on the GUI thread
            QTimer.singleShot(0, lambda: mgr.notify(type_key, title, body, actions))

    def repair_phase(self, phase: str, message: str = ""):
        """Route an auto_heal_engine phase transition into the notification
        system and, when open, the live Self-Repair HUD. Called from the GUI
        engine thread, so everything is marshalled onto the GUI thread."""
        def _apply():
            mw = self._win
            mgr = getattr(mw, "_notif_mgr", None)
            if mgr is not None:
                # One sticky multi-phase repair card (plan 2d) that also persists
                # into the notification center list on completion/failure.
                mgr.repair_update(phase, message)
            panel = getattr(mw, "_active_repair_panel", None)
            if panel is not None:
                try:
                    panel.set_repair_phase(phase, message)
                except Exception:
                    pass
        QTimer.singleShot(0, _apply)

